stream = ["a", "b", "c", "d"]
k = 2
u = {"c": 0.4, "d": 0.8}          # pre-drawn uniforms for the late items

reservoir = []
for i, item in enumerate(stream):
    if i < k:
        reservoir.append(item)          # first k items fill the reservoir
    else:
        j = int(u[item] * (i + 1))      # uniform on {0, ..., i}
        if j < k:
            reservoir[j] = item         # item evicts slot j
print(reservoir)

